// Worker Env is generated by `npm run generate-types` from wrangler.jsonc.
export type AppEnv = Env & { ADMIN_TOKEN?: string };
export interface EventRecord {
  id: string;
  title: string;
  starts_at: string;
  remaining_seats: number;
}
export interface ReserveRequest { eventId: string; email: string; seatCount: number; }
